	// 0 for a map without objects
	[[nodiscard]] constexpr std::int32_t propModelCount(std::uint32_t map)
	{
		const auto found = std::ranges::find(propModels, map, &MapPropModels::map);
		return found != propModels.end() ? found->count : 0;
	}
